-- CrediFit (BCR Challenge 2: Credit Ready) — Supabase schema, multi-company + pricing + accounts (v6)
-- Run in the Supabase SQL editor, then run seed.sql (generated by `npm run seed:sql`).
-- Safe to re-run: fresh installs get the full schema, v2 databases are upgraded in place
-- (section "Upgrade from v2" at the bottom). Nothing is ever deleted: every company,
-- invoice, assessment and portal.just.ro check stays stored and linked by company_id.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- Normalized company name: lowercase, no diacritics, no dots/punctuation,
-- legal forms (SC, SRL, SA, PFA...) removed. Mirrors normalizeCompanyName() in src/lib/company.ts.
-- ---------------------------------------------------------------------------
create or replace function public.company_name_key(raw text) returns text
language sql immutable parallel safe as $$
  select btrim(regexp_replace(regexp_replace(
           regexp_replace(
             regexp_replace(
               translate(lower(coalesce(raw, '')), 'ăâîșşțţáéíóúàèìòùäëïöü', 'aaisstt' || 'aeiouaeiouaeiou'),
               '\.', '', 'g'),
             '[^a-z0-9]+', ' ', 'g'),
           '\m(sc|srl|srld|sa|snc|scs|sca|ra|pfa|ii|if|ong)\M', ' ', 'g'),
         '\s+', ' ', 'g'))
$$;

-- ---------------------------------------------------------------------------
-- Companies — CUI and CAEN are OPTIONAL (nullable, no strict UNIQUE on empty values)
-- ---------------------------------------------------------------------------
create table if not exists public.companies (
  id                            uuid primary key default gen_random_uuid(),
  name                          text not null,
  -- lookup key when the CUI is missing (see company_name_key)
  name_key                      text not null,
  cui                           text,                       -- optional, e.g. 'RO45127893'
  caen_code                     text,                       -- optional, 4 digits
  -- benchmark sector: mapped from the CAEN code, or picked by hand ('5610', '4639', ..., 'IMM')
  sector                        text not null default 'IMM',
  ceo_name                      text not null default '',
  city                          text,
  county                        text,
  -- DECLARED by the user (not in e-Factura); DSCR is computed only once financials_declared = true
  monthly_fixed_costs           numeric(14,2) not null default 0,
  existing_monthly_debt_service numeric(14,2) not null default 0,
  financials_declared           boolean not null default false,
  -- credit lines copied from the CRC (BNR) / Biroul de Credit report: [{ lender, kind, balance, monthlyInstallment, maturity, daysLate }]
  debts                         jsonb not null default '[]'::jsonb,
  -- official name returned by ANAF for the CUI
  official_name                 text,
  -- pricing (src/lib/pricing.ts): mirror of the company's row in public.subscriptions
  plan_tier                     text not null default 'starter',
  billing_cycle                 text not null default 'monthly',
  created_at                   timestamptz not null default now(),
  updated_at                    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- e-Factura documents (UBL 2.1 / RO_CIUS), issued and received, per company
-- ---------------------------------------------------------------------------
create table if not exists public.e_invoices (
  id                   text not null,               -- "<direction>:<supplier CUI digits>:<number>"
  company_id           uuid not null references public.companies(id) on delete cascade,
  number               text not null,               -- cbc:ID
  direction            text not null check (direction in ('issued', 'received')),
  invoice_type_code    text not null default '380', -- 380 factură, 381 storno / credit note
  issue_date           date not null,               -- cbc:IssueDate
  due_date             date,                        -- cbc:DueDate
  supplier_name        text,                        -- AccountingSupplierParty
  supplier_cui         text,
  customer_name        text,                        -- AccountingCustomerParty
  customer_cui         text,
  -- the active company's name exactly as written in the XML (supplier for sales, customer for purchases)
  company_name_raw     text,
  tax_exclusive_amount numeric(14,2) not null,      -- LegalMonetaryTotal/TaxExclusiveAmount
  payable_amount       numeric(14,2),               -- LegalMonetaryTotal/PayableAmount
  currency             text not null default 'RON',
  paid_date            date,                        -- synthetic bank data (not part of e-Factura)
  source               text not null default 'xml-upload' check (source in ('synthetic', 'xml-upload', 'supabase')),
  raw_xml              text,
  created_at           timestamptz not null default now(),
  primary key (company_id, id)
);
create index if not exists e_invoices_company_date_idx on public.e_invoices (company_id, issue_date);
create index if not exists e_invoices_type_idx on public.e_invoices (company_id, invoice_type_code);

-- ---------------------------------------------------------------------------
-- Sector benchmarks (p25 / median / p75). Key = reference CAEN code, or 'IMM' (all sectors)
-- ---------------------------------------------------------------------------
create table if not exists public.sector_benchmarks (
  caen_code          text primary key,
  short_label        text,
  label              text not null,
  seasonal           boolean not null default false,
  companies          integer not null default 0,
  dso_p25            numeric, dso_median            numeric, dso_p75            numeric,
  top_client_p25     numeric, top_client_median     numeric, top_client_p75     numeric,
  credit_notes_p25   numeric, credit_notes_median   numeric, credit_notes_p75   numeric,
  seasonality_p25    numeric, seasonality_median    numeric, seasonality_p75    numeric,
  gross_margin_p25   numeric, gross_margin_median   numeric, gross_margin_p75   numeric,
  updated_at         timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Assessments (one row per saved evaluation / external quiz result)
-- ---------------------------------------------------------------------------
create table if not exists public.assessments (
  id                   uuid primary key default gen_random_uuid(),
  company_id           uuid not null references public.companies(id) on delete cascade,
  quiz_answers         jsonb,
  quiz_score           integer,
  quiz_source          text not null default 'platform' check (quiz_source in ('platform', 'external')),
  investment           jsonb,
  legal_result         jsonb,
  legal_score          numeric,
  sector               text,
  s_business           numeric,
  s_uman               numeric,
  s_investitie         numeric,
  final_score          numeric,
  status               text,
  kill_switch          boolean not null default false,
  metrics              jsonb,
  action_plan          jsonb,
  bank_recommendations jsonb,
  created_at           timestamptz not null default now()
);
create index if not exists assessments_company_idx on public.assessments (company_id, created_at desc);

-- ---------------------------------------------------------------------------
-- portal.just.ro checks (history per company; the latest one feeds S_Uman)
-- ---------------------------------------------------------------------------
create table if not exists public.legal_checks (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies(id) on delete cascade,
  company_name   text not null,
  ceo_name       text,
  source         text not null check (source in ('portal.just.ro', 'simulation', 'fallback')),
  legal_score    numeric not null,
  total_found    integer not null default 0,
  critical_count integer not null default 0,
  result         jsonb not null,
  checked_at     timestamptz not null default now(),
  created_at     timestamptz not null default now()
);
create index if not exists legal_checks_company_idx on public.legal_checks (company_id, checked_at desc);

-- ---------------------------------------------------------------------------
-- Subscriptions (one row per company; the plan gates features, see src/lib/pricing.ts).
-- companies.plan_tier / billing_cycle mirror the current row for quick reads.
-- ---------------------------------------------------------------------------
create table if not exists public.subscriptions (
  company_id    uuid primary key references public.companies(id) on delete cascade,
  plan_tier     text not null default 'starter' check (plan_tier in ('starter', 'pro', 'business')),
  billing_cycle text not null default 'monthly' check (billing_cycle in ('monthly', 'yearly')),
  status        text not null default 'active' check (status in ('active', 'trialing', 'canceled')),
  -- 'demo' = simulated checkout (hackathon), 'stripe' = real payment later
  provider      text not null default 'demo',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- B2B leads from the "Solicită Demo B2B" form (banks / financial institutions)
-- ---------------------------------------------------------------------------
create table if not exists public.b2b_leads (
  id           uuid primary key default gen_random_uuid(),
  full_name    text not null,
  organization text not null,
  email        text not null,
  phone        text,
  message      text,
  created_at   timestamptz not null default now()
);
create index if not exists b2b_leads_created_idx on public.b2b_leads (created_at desc);

-- ---------------------------------------------------------------------------
-- Real-source checks (portal.just.ro, ANAF, ANAF bilanț, VIES, ONRC state).
-- aggregate_score = ScorVerificariExterne (null when no source answered), which enters S_Uman with 50%.
-- ---------------------------------------------------------------------------
create table if not exists public.verification_reports (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  company_name      text not null,
  cui               text,
  ceo_name          text,
  aggregate_score   numeric,
  has_critical_flag boolean not null default false,
  live_sources      integer not null default 0,
  sources           jsonb not null,
  checked_at        timestamptz not null default now(),
  created_at        timestamptz not null default now()
);
create index if not exists verification_reports_company_idx on public.verification_reports (company_id, checked_at desc);

-- ---------------------------------------------------------------------------
-- Upgrade from v2 (single company, CUI NOT NULL UNIQUE). No-ops on a fresh install.
-- ---------------------------------------------------------------------------
alter table public.companies alter column cui drop not null;
alter table public.companies alter column caen_code drop not null;
alter table public.companies drop constraint if exists companies_cui_key;
alter table public.companies add column if not exists name_key text;
alter table public.companies add column if not exists sector text not null default 'IMM';
alter table public.companies add column if not exists county text;
alter table public.companies add column if not exists updated_at timestamptz not null default now();
alter table public.companies alter column ceo_name set default '';
update public.companies set ceo_name = '' where ceo_name is null;
alter table public.companies alter column ceo_name set not null;
update public.companies set cui = null where cui is not null and btrim(cui) = '';
update public.companies set caen_code = null where caen_code is not null and btrim(caen_code) = '';
update public.companies set name_key = public.company_name_key(name) where name_key is null or name_key = '';
alter table public.companies alter column name_key set not null;
update public.companies set sector = case
    when caen_code ~ '^5[56]'      then '5610'
    when caen_code ~ '^46'         then '4639'
    when caen_code ~ '^4[57]'      then '4711'
    when caen_code ~ '^1[01]'      then '1071'
    when caen_code ~ '^0[1-3]'     then '0111'
    when caen_code ~ '^49|^5[23]'  then '4941'
    when caen_code ~ '^4[123]'     then '4120'
    when caen_code ~ '^6[23]|^58'  then '6201'
    else sector end
  where caen_code is not null;

alter table public.e_invoices add column if not exists company_name_raw text;
alter table public.sector_benchmarks add column if not exists short_label text;
alter table public.sector_benchmarks add column if not exists seasonal boolean not null default false;
alter table public.assessments add column if not exists sector text;
alter table public.assessments add column if not exists bank_recommendations jsonb;

-- v4: pricing / monetization (also in supabase/migrations/20261121_pricing_multisource.sql)
alter table public.companies add column if not exists plan_tier text not null default 'starter';
alter table public.companies add column if not exists billing_cycle text not null default 'monthly';
alter table public.companies drop constraint if exists companies_plan_tier_check;
alter table public.companies add constraint companies_plan_tier_check check (plan_tier in ('starter', 'pro', 'business'));
alter table public.companies drop constraint if exists companies_billing_cycle_check;
alter table public.companies add constraint companies_billing_cycle_check check (billing_cycle in ('monthly', 'yearly'));

-- v5: real data only (also in supabase/migrations/20261121b_real_data.sql)
alter table public.companies add column if not exists financials_declared boolean not null default false;
alter table public.companies add column if not exists debts jsonb not null default '[]'::jsonb;
alter table public.companies add column if not exists official_name text;
alter table public.verification_reports alter column aggregate_score drop not null;

-- CUI unique only when it is actually filled in; companies without CUI are found by name_key.
create unique index if not exists companies_cui_unique on public.companies (cui) where cui is not null and cui <> '';
create index if not exists companies_name_key_idx on public.companies (name_key);

-- ---------------------------------------------------------------------------
-- Row Level Security
-- The Next.js API routes use the service-role key (bypasses RLS).
-- DEMO ONLY: if you run with the anon key, these permissive policies let the
-- prototype read/write. Replace them with per-user policies before production.
-- ---------------------------------------------------------------------------
alter table public.companies         enable row level security;
alter table public.e_invoices        enable row level security;
alter table public.sector_benchmarks enable row level security;
alter table public.assessments       enable row level security;
alter table public.legal_checks      enable row level security;

drop policy if exists demo_all_companies on public.companies;
drop policy if exists demo_all_invoices on public.e_invoices;
drop policy if exists demo_read_benchmarks on public.sector_benchmarks;
drop policy if exists demo_all_assessments on public.assessments;
drop policy if exists demo_all_legal_checks on public.legal_checks;

create policy demo_all_companies    on public.companies         for all    using (true) with check (true);
create policy demo_all_invoices     on public.e_invoices        for all    using (true) with check (true);
create policy demo_read_benchmarks  on public.sector_benchmarks for select using (true);
create policy demo_all_assessments  on public.assessments       for all    using (true) with check (true);
create policy demo_all_legal_checks on public.legal_checks      for all    using (true) with check (true);

alter table public.subscriptions        enable row level security;
alter table public.b2b_leads            enable row level security;
alter table public.verification_reports enable row level security;

drop policy if exists demo_all_subscriptions on public.subscriptions;
drop policy if exists demo_insert_b2b_leads on public.b2b_leads;
drop policy if exists demo_all_verification_reports on public.verification_reports;

create policy demo_all_subscriptions         on public.subscriptions        for all    using (true) with check (true);
-- leads can be submitted with the anon key but never read back with it
create policy demo_insert_b2b_leads          on public.b2b_leads            for insert with check (true);
create policy demo_all_verification_reports  on public.verification_reports for all    using (true) with check (true);

-- ---------------------------------------------------------------------------
-- v6: accounts + roles, assessment history, masked CNP, pay-per-use
-- (also in supabase/migrations/20261121c_accounts_history.sql). Requires Supabase Auth (auth.users).
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Profiles (one per Supabase Auth user) with a role: 'user' | 'admin'
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  email      text,
  full_name  text,
  role       text not null default 'user',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.profiles add column if not exists role text not null default 'user';
alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles add constraint profiles_role_check check (role in ('user', 'admin'));

-- Every new account gets a profile (role 'user'); the name typed at sign-up is copied.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data ->> 'full_name', ''))
  on conflict (id) do nothing;
  return new;
end;
$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

-- Accounts created before this migration get their profile too.
insert into public.profiles (id, email, full_name)
select u.id, u.email, coalesce(u.raw_user_meta_data ->> 'full_name', '') from auth.users u
on conflict (id) do nothing;

alter table public.profiles enable row level security;
drop policy if exists profiles_select_own on public.profiles;
-- A user can read only their own profile; roles are changed only with the service role / SQL editor.
create policy profiles_select_own on public.profiles for select using (auth.uid() = id);

-- Make an account admin (run in the SQL editor with the real email):
--   update public.profiles set role = 'admin' where email = 'admin@exemplu.ro';

-- ---------------------------------------------------------------------------
-- Companies: owner account, masked CNP of the administrator, pay-per-use
-- ---------------------------------------------------------------------------
alter table public.companies add column if not exists user_id uuid references auth.users(id) on delete set null;
-- Only the masked form "1900101******" is ever stored (never the full CNP).
alter table public.companies add column if not exists ceo_cnp_masked text;
alter table public.companies drop constraint if exists companies_ceo_cnp_masked_check;
alter table public.companies add constraint companies_ceo_cnp_masked_check check (ceo_cnp_masked is null or ceo_cnp_masked ~ '^[0-9]{7}\*{6}$');
-- Hints derived from the CNP to tell namesakes apart: { birthDate, sex, countyCode, county }.
alter table public.companies add column if not exists ceo_cnp_info jsonb;
alter table public.companies add column if not exists pay_per_use_unlocked boolean not null default false;
alter table public.companies add column if not exists purchased_credits integer not null default 0;
create index if not exists companies_user_idx on public.companies (user_id);

-- ---------------------------------------------------------------------------
-- Subscriptions: pay-per-use analyses next to the monthly / yearly plans
-- ---------------------------------------------------------------------------
alter table public.subscriptions add column if not exists pay_per_use boolean not null default false;
alter table public.subscriptions add column if not exists purchased_credits integer not null default 0;

-- ---------------------------------------------------------------------------
-- Assessment history: one immutable snapshot per saved evaluation
-- ---------------------------------------------------------------------------
create table if not exists public.assessment_history (
  id                   uuid primary key default gen_random_uuid(),
  company_id           uuid not null references public.companies(id) on delete cascade,
  user_id              uuid references auth.users(id) on delete set null,
  final_score          numeric not null,
  s_business           numeric not null,
  s_uman               numeric not null,
  s_investitie         numeric not null,
  dscr                 numeric,
  dso                  numeric not null,
  client_concentration numeric not null,
  requested_amount     numeric,
  status               text,
  snapshot_json        jsonb not null default '{}'::jsonb,
  created_at           timestamptz not null default now()
);
create index if not exists assessment_history_company_idx on public.assessment_history (company_id, created_at desc);
create index if not exists assessment_history_user_idx on public.assessment_history (user_id);

alter table public.assessment_history enable row level security;
drop policy if exists demo_all_assessment_history on public.assessment_history;
-- DEMO ONLY (same as the other tables): the API routes use the service-role key.
create policy demo_all_assessment_history on public.assessment_history for all using (true) with check (true);

